    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateConflict() throws Exception {
        String lastName = "Duplicateowner";
        newOwner(lastName);
        String body = """
            {"firstName":"George","lastName":"%s","address":"110 W. Liberty St.","city":"Madison","telephone":"6085551023"}
